<template><view class="member-page"><NativeStatusSpacer/><view class="navigation"><button class="back" @tap="back">‹</button><text>{{mode==='ASSOCIATE'?'关联已有用户':'新增成长小主人账号'}}</text></view><view class="paper"><text v-if="error" class="error">{{error}}</text><text v-if="loading" class="state">正在加载</text><template v-if="classInfo"><text class="class-name">{{classInfo.name}}</text><text v-if="!created&&!linked" class="mode-label">选择关联方式</text><view class="tabs"><button :class="{active:mode==='ASSOCIATE'}" :disabled="busy||!canAssign" @tap="changeMode('ASSOCIATE')"><text>已有账号</text><text class="mode-note">通过四位登录码验证</text></button><button :class="{active:mode==='CREATE'}" :disabled="busy||!canCreate" @tap="changeMode('CREATE')"><text>新建账号</text><text class="mode-note">创建专属成长账号</text></button></view><template v-if="!created&&!linked"><template v-if="mode==='CREATE'"><text class="field-label">成长小主人姓名<text class="required">*</text></text><input v-model="name" maxlength="64" :disabled="busy||uncertain" placeholder="请输入姓名"/><text class="help">创建后直接加入当前班级，并生成账号和四位登录码。</text></template><template v-else><ClassAccountAssociation :token="token" :school-id="schoolId" :class-id="id" @linked="linked=true"/></template><button v-if="mode==='CREATE'" class="primary" :loading="saving" :disabled="busy||uncertain||(mode==='CREATE'?!canCreate:!canAssign)" @tap="submit">{{mode==='CREATE'?'创建并加入班级':'确认关联'}}</button></template><view v-if="created" class="result"><text class="result-title">创建成功</text><view><text>账号</text><text>{{created.studentAccount}}</text></view><view><text>四位登录码</text><text>{{created.initialLoginCode}}</text></view><text class="help">请妥善保存登录码；离开本页后不再显示。</text></view><view v-if="linked" class="result"><text class="result-title">已加入当前班级</text></view><button v-if="created||linked||uncertain" class="secondary" @tap="back">返回班级核对</button></template></view></view></template>
<script setup lang="ts">
import ClassAccountAssociation from '@/components/ClassAccountAssociation.vue';
import {ref,computed} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';import {getOrganizationSession} from '@/session/organization-session';import {request} from '@/api/http';import {listManagedClasses,type OrganizationClass} from '@/api/organization-classes';import {listOrganizationStudents,type OrganizationStudentRelationship} from '@/api/organization-students';import {classMemberApi,type CreatedClassChild} from '@/api/class-members';import {unassignedClassCandidates,classMemberName} from '@/models/class-member-draft';
const classInfo=ref<OrganizationClass|null>(null),candidates=ref<OrganizationStudentRelationship[]>([]),name=ref(''),keyword=ref(''),selectedId=ref(''),mode=ref<'CREATE'|'ASSOCIATE'>('CREATE'),created=ref<CreatedClassChild|null>(null),linked=ref(false),loading=ref(false),saving=ref(false),uncertain=ref(false),error=ref(''),canCreate=ref(false),canAssign=ref(false);const busy=computed(()=>loading.value||saving.value),filteredCandidates=computed(()=>candidates.value.filter(c=>c.studentName.includes(keyword.value.trim())));let id='',token='',schoolId='',revision=0,visible=false;
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function sameScope(){const s=selection();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===schoolId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function current(n:number){return visible&&revision===n&&sameScope();}
onLoad(q=>{id=typeof q?.classId==='string'?q.classId:'';});onShow(()=>{visible=true;void load();});
function hide(){visible=false;classInfo.value=null;if(saving.value)uncertain.value=true;++revision;saving.value=false;loading.value=false;if(created.value)linked.value=true;created.value=null;candidates.value=[];}onHide(hide);onUnload(hide);
async function load(){const n=++revision,nextToken=getOrganizationSession()?.accessToken||'',s=selection();if(token&&token!==nextToken){name.value='';uncertain.value=false;created.value=null;linked.value=false;}token=nextToken;schoolId=s?.organizationId||'';loading.value=true;error.value='';classInfo.value=null;canCreate.value=false;canAssign.value=false;let checked=false;try{if(!/^[1-9]\d*$/.test(id)||!sameScope())throw Error('请从当前学校或培训机构的班级进入');checked=true;const me=await request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});if(!current(n))return;if(!me.permissionCodes.includes('CLASS_READ'))throw Error('当前账号没有班级查看权限');const rows=await listManagedClasses(token);if(!current(n))return;const c=rows.find(c=>c.id===id&&c.schoolOrganizationId===schoolId);if(!c||c.status!=='ENABLED'||c.effectiveStatus!=='ENABLED')throw Error('当前班级不可用或已超出组织范围');canCreate.value=me.permissionCodes.includes('STUDENT_CREATE')&&me.permissionCodes.includes('STUDENT_CLASS_ASSIGN');canAssign.value=me.permissionCodes.includes('STUDENT_CLASS_ASSIGN')&&me.permissionCodes.includes('STUDENT_ORGANIZATION_MANAGE');if(!canCreate.value&&!canAssign.value)throw Error('当前账号没有新增班级成员权限');if(canAssign.value){const members=await listOrganizationStudents(token);if(!current(n))return;candidates.value=unassignedClassCandidates(members,schoolId);}if(!canCreate.value)mode.value='ASSOCIATE';classInfo.value=c;if(uncertain.value)error.value='上次操作结果待确认，请先返回班级核对。';}catch(e){if((!checked&&visible&&n===revision)||current(n))error.value=e instanceof Error?e.message:'加载失败';}finally{if(n===revision)loading.value=false;}}
function changeMode(next:'CREATE'|'ASSOCIATE'){if(busy.value||uncertain.value||(next==='CREATE'?!canCreate.value:!canAssign.value))return;mode.value=next;error.value='';selectedId.value='';}
function choose(studentId:string){if(!busy.value&&!uncertain.value&&candidates.value.some(c=>c.studentId===studentId))selectedId.value=studentId;}
async function submit(){if(busy.value||uncertain.value||!classInfo.value||created.value||linked.value)return;const n=revision;error.value='';let scopeChecked=false;try{if(!current(n))throw Error('组织或账号已变化，请返回重新进入');scopeChecked=true;if(mode.value==='CREATE'){if(!canCreate.value)throw Error('没有创建权限');const value=classMemberName(name.value);saving.value=true;const result=await classMemberApi.create(token,schoolId,id,value);if(current(n)){created.value=result;name.value='';}else uncertain.value=true;}else{if(!canAssign.value||!candidates.value.some(c=>c.studentId===selectedId.value))throw Error('请选择本校未分班成员');saving.value=true;await classMemberApi.assign(token,schoolId,selectedId.value,id);if(current(n))linked.value=true;else uncertain.value=true;}}catch(e){if(current(n)||!scopeChecked&&visible&&n===revision)error.value=e instanceof Error?e.message:'操作未能完成';}finally{if(n===revision)saving.value=false;}}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/organization-class-detail/organization-class-detail?classId='+encodeURIComponent(id)})});}
</script>
<style scoped>.member-page{min-height:100vh;background:#f7faf7;color:#183c30}.navigation{position:relative;height:88rpx;display:flex;align-items:center;justify-content:center;font-size:30rpx;font-weight:650;background:white}.back{position:absolute;left:18rpx;top:0;margin:0;padding:0;width:50rpx;height:88rpx;line-height:78rpx;font-size:58rpx;background:transparent;color:#174b37}button::after{border:0}.paper{padding:28rpx 30rpx 50rpx;background:white;border-radius:28rpx}.class-name{display:block;font-size:29rpx;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:20rpx}.tabs{display:flex;background:#f1f4f2;border-radius:18rpx;padding:4rpx;margin-bottom:28rpx}.tabs button{flex:1;margin:0;font-size:27rpx;padding:0;line-height:68rpx;background:transparent;color:#78877f;border-radius:15rpx;border-bottom:4rpx solid transparent}.tabs .active{background:white;color:#146446;border-bottom-color:#146446;font-weight:650}.field-label{font-size:28rpx;display:block;margin-bottom:15rpx}.required{color:#cf5c50;margin-left:8rpx}input{padding:16rpx 20rpx;border:1rpx solid #dfe7e1;border-radius:16rpx;height:54rpx;font-size:28rpx;background:#fafcfb}.help{display:block;font-size:24rpx;color:#87958b;line-height:1.7;margin-top:16rpx}.primary,.secondary{width:100%;margin-top:30rpx;border-radius:20rpx;font-size:29rpx;line-height:88rpx;background:#145c44;color:white}.primary[disabled]{background:#a7bdb1;color:#fff}.secondary{background:#edf5ef;color:#205840}.state,.error{display:block;padding:16rpx 0;font-size:26rpx;line-height:1.6;color:#8a978e}.error{color:#ae4f45}.candidate{display:flex;align-items:center;gap:18rpx;padding:20rpx 0;border-bottom:1rpx solid #e5ede6}.candidate image{width:66rpx;height:66rpx;border-radius:50%}.candidate>text{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:28rpx}.radio{width:30rpx;height:30rpx;border-radius:50%;border:2rpx solid #a5b8aa;display:flex;align-items:center;justify-content:center}.radio view{width:20rpx;height:20rpx;border-radius:50%;background:#176346}.result-title{display:block;font-size:32rpx;font-weight:650;margin:25rpx 0}.result>view{display:flex;gap:25rpx;justify-content:space-between;padding:22rpx 0;border-bottom:1rpx solid #e5eee7;font-size:28rpx}.result>view>text:last-child{overflow-wrap:anywhere;text-align:right}</style>
<style scoped>.class-name{display:none}.paper{border-radius:0;padding-top:18rpx}.member-page{background:#fff}</style>

<style scoped>.member-page{background:linear-gradient(110deg,#206b52,#0c4f3e);min-height:100vh}.navigation{background:transparent;color:white}.back{color:white}.paper{border-radius:28rpx 28rpx 0 0;min-height:calc(100vh - 170rpx);box-sizing:border-box;background:#fbfdfb;padding-top:28rpx}.mode-label{display:block;font-size:26rpx;font-weight:650;margin-bottom:16rpx}.tabs{gap:16rpx;background:transparent;padding:0}.tabs button{border:1rpx solid #e2e8e4;background:#f2f5f4;border-radius:15rpx;padding:12rpx 8rpx;line-height:1.5}.tabs button text{display:block}.tabs button .mode-note{font-size:21rpx;font-weight:400;margin-top:7rpx}.tabs button.active{border:2rpx solid #176346;background:#edf8ee}.mode-note{color:#789086}.tabs button.active .mode-note{color:#237b4f}</style>
